__NUXT_JSONP__("/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"en",pageTitle:"Change of Status | Mentor Language Institute",pageDescription:"Thank you very much for your interest in enrolling in MLI.",title:"Change of Status",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["Thank you very much for your interest in enrolling in MLI.\u003Cbr \u002F\u003EThis page is for those currently in the U.S. without an F1 (student) VISA and would like to change to F1 status.","If you wish to apply please proceed:"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-en.jpg",link:"\u002Fen\u002Fadmission"}},applicationSteps:{title:"Application Steps",description:["The exact application steps is dependent on a person's country, nationality, course, visa to obtain, etc. Our staff will be happy to guide you on the appropriate steps based on your unique situation."]},needHelp:{title:"Need help? Ask Us!",description:["Visa Rules and application steps are different based on your current status.\u003Cbr \u002F\u003EIf you need clarification before applying, please feel free to contact us. We have staff fluent in 8 languages!"]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-en.png",link:"\u002Fen\u002Fcontact",title:"Contact Us",lists:[{campus:"＜WESTWOOD CAMPUS＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜HOLLYWOOD CAMPUS＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:28.789Z",updatedAt:"2025-05-26T12:06:27.712Z"}}],fetch:{},mutations:void 0});